<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Class Notes</span></nav><h1>Class Notes</h1><p>Publish class- and subject-scoped learning resources securely.</p></div></header><form class="module-card" method="post" enctype="multipart/form-data" action="<?=url('/admin/notes')?>"><?=csrf_field()?><header class="module-card__header"><h2>Publish Note</h2></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Class</label><select class="module-select" id="noteClass" name="class_id" required><option value="">-- Select a class --</option><?php foreach($classes as$c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></div><div class="module-field"><label>Subject</label><select class="module-select" name="subject_id" required data-subject-filter="#noteClass"><option value="">-- Select a subject --</option><?php foreach($classes as$c):foreach($c['subjects']??[] as$s):?><option value="<?=$s['id']?>" data-class="<?=$c['id']?>"><?=e($s['name'])?></option><?php endforeach;endforeach?></select></div><div class="module-field"><label>Teacher</label><select class="module-select" name="teacher_id"><option value="">Admin</option><?php foreach($teachers as$t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach?></select></div><div class="module-field"><label>Title</label><input class="module-input" name="title" required maxlength="160"></div><div class="module-field"><label>Chapter / Topic</label><input class="module-input" name="chapter"></div><div class="module-field"><label>Publish date</label><input class="module-input" type="date" name="publish_date" value="<?=date('Y-m-d')?>" required></div><div class="module-field field--wide"><label>Description</label><textarea class="module-textarea" name="description"></textarea></div><div class="module-field"><label>Attachment</label><input class="module-input" type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"></div><div class="module-field"><label>Status</label><select class="module-select" name="status"><option value="published">Published</option><option value="draft">Draft</option></select></div></div></div><footer class="module-card__footer"><button class="btn btn--primary">Save Note</button></footer></form><section class="module-card"><header class="module-card__header"><h2>Published Resources</h2></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Title</th><th>Class</th><th>Subject</th><th>Teacher</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($notes as$n):?><tr><td><?=e($n['publish_date'])?></td><td><strong><?=e($n['title'])?></strong><br><small><?=e($n['chapter']??'')?></small></td><td><?=e($n['class_name'])?></td><td><?=e($n['subject_name'])?></td><td><?=e($n['teacher']??'Admin')?></td><td><span class="status-badge status-badge--<?=e($n['status'])?>"><?=e(ucfirst($n['status']))?></span></td><td><form method="post" action="<?=url('/admin/notes/'.$n['id'].'/delete')?>"><?=csrf_field()?><button class="class-action-button class-action-button--danger"><i data-lucide="trash-2"></i></button></form></td></tr><?php endforeach?><?php if(!$notes):?><tr><td colspan="7"><div class="compact-empty"><h3>No class notes yet</h3><p>Published learning resources will appear here.</p></div></td></tr><?php endif?></tbody></table></div></div></section></div></div></main>
